:root {
  --cream: #f5ead6;
  --brown-dark: #4a2f1a;
  --brown-mid: #7a4e2d;
  --brown-light: #b07d50;
  --gold: #c9a84c;
  --text-muted: #8c6a45;
  --badge-bg: #4a2f1a;
  --badge-text: #f5ead6;
}

article.sundial-marker {
  background-color: var(--cream);
  border: 3px solid var(--brown-mid);
  border-radius: 6px;
  width: 260px;
  padding: 0;
  margin: 0 auto;
  overflow: hidden;
}

.marker-header {
  background-color: var(--brown-dark);
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 16px;
}

.marker-icon {
  font-size: 20px;
  line-height: 1;
}

.marker-title {
  font-size: 17px;
  font-weight: 700;
  color: var(--cream);
  margin: 0;
  letter-spacing: 0.04em;
}

.marker-body {
  padding: 14px 16px 10px;
}

.marker-subtitle {
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--text-muted);
  margin: 0 0 2px;
}

.marker-coords {
  font-size: 22px;
  font-weight: 700;
  color: var(--brown-dark);
  margin: 0 0 12px;
  letter-spacing: 0.02em;
}

.marker-details {
  list-style: none;
  margin: 0;
  padding: 0;
  border-top: 1px solid var(--brown-light);
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding-top: 8px;
}

.marker-details li {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
}

.detail-label {
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
}

.detail-value {
  font-size: 13px;
  font-weight: 600;
  color: var(--brown-dark);
}

.marker-footer {
  background-color: var(--gold);
  display: flex;
  justify-content: center;
  padding: 7px 16px;
  margin-top: 10px;
}

.marker-badge {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--badge-bg);
}
